# Dynamic dispatch at nested call sites: a method call with a statically
# unknown receiver used as a value inside arithmetic, as a function argument,
# in a return, and assigned to a variable. Exercises the AOT dispatch switch
# from every expression position (all-call-site dispatch).
class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
def add(a, b):
    return a + b
def get(v):
    return v.speak()
print(make(1).speak() + make(2).speak())
print(add(make(1).speak(), make(2).speak()))
print(get(make(1)) + get(make(2)))
c = Animal()
d = Dog()
print(c.speak() + d.speak())
print("done")

# Gap A reproducer: an instance handle stored in a local variable must stay
# alive across a later allocation that triggers GC. Expected: 43.
class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
def f():
    a = make(1)
    b = make(2)
    return a.speak() + b.speak()
print(f())

# Gap A (ADR 0151): a polymorphic receiver that survives many real GC
# collections + slot reuse must dispatch on the *live* instance. Unlike
# dispatch_gc.gy (2 allocations, no collection), this forces the 1024-slot
# heap to fill and free/reuse slots repeatedly while two receivers stay
# reachable, then dispatches on both. Expected: 1 + 42 = 43.
class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
def f():
    a = make(1)
    b = make(2)
    for i in range(2000):
        lst = [i]
    return a.speak() + b.speak()
print(f())

def add1(g):
    def wrap(x):
        return g(x) + 1
    return wrap
@add1
def f(x):
    return x * 2
print(f(3))

# Helpers are declared where they read best, not in call order. This is the shape the
# checker used to refuse: a body calls a function whose def is further down the file,
# including a pair of functions that call each other. A body runs later, when the name is
# bound — which is what both backends already assumed.

def is_even(n):
    if n == 0:
        return True
    return is_odd(n - 1)


def is_odd(n):
    if n == 0:
        return False
    return is_even(n - 1)


def describe(n):
    return classify(n)


def classify(n):
    if n == 0:
        return "zero"
    if is_even(n):
        return "even"
    return "odd"


def pair(n):
    return two(n)


def two(n):
    return n * 2


print(1 if is_even(4) else 0)
print(1 if is_odd(3) else 0)
print(describe(0))
print(describe(6))
print(describe(7))
print(pair(21))

# A module function and a method may share a name: they live in different places, and the
# checker's function table used to give them one key. The method overwrote the module function,
# so `time(1)` below was analyzed against the *method* — whose arity includes `self` — and the
# last parameter came out unbound, reporting `undefined name "x"` on the method's own body while
# the program was ordinary and correct (roadmap Gap R.8, ADR 0200).
#
# The same shape recurs whenever a class's vocabulary matches a helper's: `area`, `run`, `time`,
# `send`, `open`. All four paths now agree on the answer.

def time(x):
    return x + 5


class Timer:
    def time(self, x):
        return x * 3

    def run(self, x):
        return self.time(x) + 1


def area(w, h):
    return w * h


class Rect:
    def area(self):
        return 6

    def doubled(self):
        return self.area() * 2


print(time(1))
print(Timer().run(2))
print(area(2, 3))
print(Rect().doubled())

# Division by zero is a ZeroDivisionError, on every path: it is raised, it is catchable, and
# the message is the one CPython uses for the same operation. The compiled backend used to
# lower the instruction and keep walking — `print(1 / 0)` printed `inf`, and `print(7 % 0)`
# printed a different garbage number on every run — while the interpreter reported a message
# with no exception class, so `except ZeroDivisionError:` matched nothing (Gap R.18, ADR 0212).
def zero():
    return 0

print(10 / 5)
print(6 // 3)
print(7 % 4)

try:
    print(1 / 0)
except ZeroDivisionError:
    print("caught division")

try:
    print(7 % 0)
except ZeroDivisionError:
    print("caught modulo")

try:
    print(7 // 0)
except ZeroDivisionError:
    print("caught floor division")

try:
    print(1.0 % 0)
except ZeroDivisionError:
    print("caught float modulo")

try:
    print(10 / zero())
except ZeroDivisionError:
    print("caught a divisor computed at run time")

# The arms of a `try` are dispatched in the order they are written, and an exception no arm
# matches belongs to an enclosing scope. The compiled backend used to lower only the first arm
# and then clear the exception flag, so a later arm never ran and an unhandled exception
# vanished with no traceback and exit 0 (Gap R.20, ADR 0213).
try:
    xs = [1]
    print(xs[5])
except KeyError:
    print("not this one")
except IndexError:
    print("second arm")

try:
    d = {}
    print(d[9])
except IndexError:
    print("not this either")
except ValueError:
    print("nor this")
except KeyError:
    print("third arm")

try:
    print(1 / 0)
except KeyError:
    print("no")
except:
    print("bare arm")

try:
    try:
        ys = []
        print(ys.pop())
    except KeyError:
        print("inner does not take IndexError")
except IndexError:
    print("outer arm")

try:
    raise RuntimeError("carried outward")
except Exception:
    print("exception base")

# A `finally` is a deferred body: it runs on every exit from its `try` -- fall-through, a handled
# exception, a propagating one, and the transfers (`return`, `break`, `continue`) that leave the
# block. An `except` arm catches exceptions, never a transfer (roadmap Gap R.23, ADR 0222).
# CPython prints exactly this, on this file.

def value_before_finally() -> int:
    n = 1
    try:
        return n
    finally:
        n = 99
        print("fin", n)


def nested() -> int:
    try:
        try:
            return 1
        finally:
            print("inner")
    finally:
        print("outer")


def winner() -> int:
    try:
        return 1
    finally:
        return 2


def propagates() -> int:
    try:
        x = 1 / 0
    finally:
        print("prop fin")
    return 0


def from_arm() -> int:
    try:
        x = 1 / 0
    except:
        return 7
    finally:
        print("arm fin")
    return 0


def twice() -> int:
    try:
        return 5
    finally:
        print("once")


print(twice())
print(twice())
print(value_before_finally())
print(nested())
print(winner())
print(from_arm())

try:
    print(propagates())
except:
    print("caught")

for i in range(3):
    try:
        continue
    finally:
        print("cont fin", i)

for i in range(3):
    try:
        break
    finally:
        print("brk fin", i)

for i in range(4):
    try:
        print("body", i)
    except:
        print("arm that never runs")
    finally:
        print("loop fin", i)

def ignores_transfers() -> int:
    try:
        return 1
    except:
        print("an arm cannot catch a return")
    return 3

print(ignores_transfers())

# A method is a call like any other: it has its own unwind target, and its body owes the same
# duties a function body owes -- a deferred `finally` on every exit, and an exception that
# propagates to whoever called it (roadmap Gap R.41, ADR 0223). CPython prints exactly this.
class Worker:
    def cleanup(self) -> int:
        try:
            return 3
        finally:
            print("fin")

    def handled(self) -> int:
        try:
            x = 1 / 0
        except:
            print("handled")
        return 4

    def raiser(self) -> int:
        raise ValueError("boom")

    def calls_raiser(self) -> int:
        return self.raiser()

    def loops(self) -> int:
        for i in range(3):
            try:
                break
            finally:
                print("loop fin")
        return 9


print(Worker().cleanup())
print(Worker().handled())
print(Worker().loops())

try:
    print(Worker().raiser())
except ValueError:
    print("caught value error")

try:
    print(Worker().calls_raiser())
except:
    print("caught from the nested call")

# Variance + generics (L6.6): nominal class annotations accept subclass
# instances, read-only Sequence annotations accept any container, and invariant
# list/dict annotations keep their element types — identical on both backends.

class Animal:
    def speak(self):
        return 1

class Dog(Animal):
    def speak(self):
        return 2

class Puppy(Dog):
    def speak(self):
        return 3

# a nominal base-class annotation accepts instances of the class and subclasses
def feed(a: Animal) -> int:
    return a.speak()

print(feed(Animal()))
print(feed(Dog()))
print(feed(Puppy()))

