# integration/programs/entry_lambda_capture.gy — an entry lambda reads the frame
# its application is written in, and the clone the pass mints carries the words
# (roadmap L11.7 · Gap R.336 · ADR 0395). CPython is the oracle; the conformance
# matrix asserts this program byte-for-byte, and the two legs that witness it are
# the record (pkg/lang/testdata/interpreter-golden.json) and this compiled run.

def apply1(fn, v):
    return fn(v)

def apply2(fn, v):
    return fn(v)

def twice(fn, v):
    return fn(fn(v))

# The entry reads a local of the frame its application is written in: the reference's 4.
def from_local(seed):
    base = 1
    return apply1(lambda x: x + base, seed)

# The entry reads a parameter of that frame: the reference's 8 for use(5).
def from_param(seed):
    return apply1(lambda x: x + seed, seed)

# The entry reads the loop target of that frame: the reference's 2 and 3.
def from_loop(seed):
    total = 0
    for i in [1, 2]:
        total = total + apply1(lambda x: x + i, seed)
    return total

# Two entries of one callee, each reading its own name of the frame: 13 for 3 + 10.
def two_entries(seed):
    left = 10
    right = 2
    return apply2(lambda x: x + left, seed) + apply2(lambda x: x + right, seed)

# A capturing entry and a closed entry of the same callee: 4 + 7.
def mixed(seed):
    offset = 1
    return apply1(lambda x: x + offset, seed) + apply1(lambda x: x + 4, 3)

# The entry reads a module-level name, which is no capture at all: 14.
LIMIT = 10

def from_module(_ignored):
    return apply1(lambda x: x + LIMIT, 4)

# The callee is called twice by the same body, so the forwarded word crosses twice.
def called_twice(seed):
    step = 2
    return twice(lambda x: x + step, seed) + apply1(lambda x: x + step, seed)

print(from_local(3))
print(from_param(5))
print(from_loop(10))
print(two_entries(3))
print(mixed(3))
print(from_module(0))
print(called_twice(1))

# What an `except <Type> as name:` clause binds (roadmap Gap R.113, ADR 0406).
#
# The arm names what it took, and the name holds what the exception WRITES: the message the raise
# carried, interned by the one door every other text goes through. Every line below prints the bytes
# CPython prints for the same line — the reference hands the arm an exception OBJECT and prints that
# object's message, and this backend, whose value is one word wide, gives the name exactly that half.
#
# The half it does not have is roadmap Gap R.395 and is written out in `integration/except_as_name_test.go`
# with the reference's bytes beside it: `repr(err)`, `err.args`, `type(err)`, what the name does after the
# arm, and the operand doors (`len`, a text method, `==`), which are refused here rather than answered with
# the message dressed up as the object (ADR 0166).

# a machine raise names itself
try:
    1 / 0
except ZeroDivisionError as err:
    print(err)

# the message a `raise` carried
try:
    raise ValueError("boom")
except ValueError as err:
    print(err)

# the colon inside a message belongs to the message
try:
    raise RuntimeError("a: b")
except RuntimeError as err:
    print(err)

# a raise that carried nothing carries the empty text
try:
    raise IndexError
except IndexError as err:
    print("[" + str(err) + "]")

# the name inside an interpolation
try:
    int("x")
except ValueError as err:
    print(f"caught: {err}")

# the second arm is the one that matches, and only it binds
try:
    1 / 0
except TypeError as te:
    print("te", te)
except ZeroDivisionError as ze:
    print("ze", ze)

# the catch-all arm names it too
try:
    print([1][9])
except Exception as err:
    print("any", err)

# an arm that calls, then reads the name
def note():
    print("arm ran")

d = {}
try:
    print(d["k"])
except KeyError as err:
    note()
    print("after", err)

# an inner arm that re-raises for the outer arm's name
try:
    try:
        1 / 0
    except ZeroDivisionError as inner:
        print("inner", inner)
        raise ValueError("second")
