print(1 in c.counted())
print(9 in c.counted())
s = 0
for v in c.counted():
    s = s + v
print(s)
for v in c.count(3):
    print(v)
print(c.via_self())
d = Child()
print(d.drain())
for v in d.gen():
    print(v)
total = 0
for k in range(3):
